int lengthOfLongestSubstring(char* s) {
    int last[256];
    for(int i = 0; i < 256; i++) last[i] = -1;
    int left = 0, maxLen = 0, i = 0;
    while(s[i] != '\0') {
        unsigned char c = (unsigned char)s[i];
        if (last[c] >= left) left = last[c] + 1;
        last[c] = i;
        int len = i - left + 1;
        if (len > maxLen) maxLen = len;
        i++;
    }
    return maxLen;
}

